// Verification-only launcher: exposes the real start-up exception and issues more than one one-use loopback
// launch link so a browser session and a scripted API probe can each consume their own.
import io.github.diodeme.ji.cli.LocalHostApplication;

public final class VerifyHostLauncher {
    public static void main(String[] args) throws Exception {
        int links = args.length == 0 ? 1 : Integer.parseInt(args[0]);
        try (var host = LocalHostApplication.open(System.getenv())) {
            for (int index = 0; index < links; index++) System.out.println(host.launchUri());
            System.out.flush();
            Thread.currentThread().join();
        }
    }
}
